'use client';

import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';
import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useState } from 'react';

import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

import { DEFAULT_FEATURE_ID, FEATURES, type FeatureId, SECTION } from './data';
import { FeaturePreview } from './feature-previews';

const CROSSFADE_TRANSITION: Transition = {
  duration: 0.22,
  ease: [0.23, 1, 0.32, 1],
};

const CROSSFADE_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(4px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(4px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function crossfadeVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return CROSSFADE_VARIANTS;
}

function isFeatureId(value: unknown): value is FeatureId {
  return FEATURES.some((feature) => feature.id === value);
}

function tabIdOf(id: FeatureId) {
  return `features-03-tab-${id}`;
}

function panelIdOf(id: FeatureId) {
  return `features-03-panel-${id}`;
}

export default function Features03() {
  const [activeId, setActiveId] = useState<FeatureId>(DEFAULT_FEATURE_ID);
  const shouldReduceMotion = useReducedMotion();
  const crossfadeVariants = crossfadeVariantsOf(shouldReduceMotion);

  function pickFeature(value: unknown) {
    if (isFeatureId(value)) {
      setActiveId(value);
    }
  }

  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 sm:gap-14'>
        <div className='flex max-w-2xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.description}
          </p>
        </div>
        <TabsPrimitive.Root
          value={activeId}
          onValueChange={pickFeature}
          orientation='vertical'
          className='grid items-start gap-8 lg:grid-cols-[minmax(0,2fr)_minmax(0,3fr)] lg:gap-12'
        >
          <TabsPrimitive.List
            aria-label='Loomboard views'
            className='relative flex flex-col gap-1'
          >
            {FEATURES.map((feature) => (
              <TabsPrimitive.Tab
                key={feature.id}
                value={feature.id}
                id={tabIdOf(feature.id)}
                aria-controls={panelIdOf(feature.id)}
                className='group/feature focus-visible:ring-ring/25 hover:bg-foreground/[0.025] relative z-10 flex w-full cursor-pointer items-start gap-3 rounded-xl p-3 text-left transition-colors outline-none focus-visible:ring-[3px] sm:p-4'
              >
                <span className='keycap-3d text-muted-foreground group-data-active/feature:text-primary-ink flex size-8 shrink-0 items-center justify-center rounded-lg transition-colors'>
                  <feature.icon />
                </span>
                <span className='flex flex-col gap-1'>
                  <span className='text-muted-foreground group-data-active/feature:text-foreground text-sm font-medium transition-colors'>
                    {feature.title}
                  </span>
                  <span className='text-muted-foreground text-[13px] leading-relaxed text-pretty'>
                    {feature.description}
                  </span>
                </span>
              </TabsPrimitive.Tab>
            ))}
            <TabsPrimitive.Indicator className='bg-foreground/[0.04] before:bg-primary dark:bg-foreground/[0.06] pointer-events-none absolute top-0 left-0 h-(--active-tab-height) w-full translate-y-(--active-tab-top) rounded-xl transition-[translate,height] duration-300 ease-(--ease-out-strong) before:absolute before:inset-y-3 before:left-0 before:w-0.5 before:rounded-full' />
          </TabsPrimitive.List>
          <div className='bg-foreground/[0.025] rounded-2xl p-4 sm:p-8'>
            <AnimatedSize contentClassName='relative'>
              <AnimatePresence mode='popLayout' initial={false}>
                <motion.div
                  key={activeId}
                  id={panelIdOf(activeId)}
                  role='tabpanel'
                  aria-labelledby={tabIdOf(activeId)}
                  tabIndex={0}
                  variants={crossfadeVariants}
                  initial='enter'
                  animate='visible'
                  exit='exit'
                  transition={CROSSFADE_TRANSITION}
                  className='focus-visible:ring-ring/25 rounded-xl outline-none focus-visible:ring-[3px]'
                >
                  <FeaturePreview id={activeId} />
                </motion.div>
              </AnimatePresence>
            </AnimatedSize>
          </div>
        </TabsPrimitive.Root>
      </div>
    </section>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import { Switch } from '@/registry/ndeko/ui/switch';

import {
  type DayHours,
  type FeatureId,
  HOURS_BY_DAY,
  MINI_LANES,
  RULE,
  TIMELINE_BARS,
  type TimelineBar,
  WEEK_DAYS,
} from './data';

const CARD =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.05] rounded-lg shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

const CHART = {
  width: 320,
  height: 176,
  left: 30,
  right: 6,
  top: 10,
  bottom: 26,
  maxHours: 8,
  gridStep: 2,
  barRatio: 0.48,
};

const HOURS_FORMAT = new Intl.NumberFormat('en', {
  maximumFractionDigits: 1,
});

function BoardsPreview() {
  return (
    <div className='grid grid-cols-3 gap-2 sm:gap-3'>
      {MINI_LANES.map((lane) => (
        <div
          key={lane.title}
          className='bg-foreground/[0.03] flex min-w-0 flex-col gap-2 rounded-lg p-1.5 sm:p-2'
        >
          <div className='flex items-center justify-between gap-1 px-1 pt-0.5'>
            <span className='truncate text-xs font-medium'>{lane.title}</span>
            <Kbd>{lane.cards.length}</Kbd>
          </div>
          {lane.cards.map((card) => (
            <div
              key={card.title}
              className={cn(CARD, 'flex flex-col gap-2 p-2')}
            >
              <p className='line-clamp-2 text-xs leading-snug font-medium'>
                {card.title}
              </p>
              <Chip color='var(--muted-foreground)'>{card.label}</Chip>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

function gridColumnOf(bar: TimelineBar) {
  return `${bar.startDay} / span ${bar.dayCount}`;
}

function TimelinePreview() {
  return (
    <div className='flex flex-col gap-2'>
      <div className='grid grid-cols-5 gap-1.5'>
        {WEEK_DAYS.map((day) => (
          <span
            key={day}
            className='text-muted-foreground px-1 text-xs font-medium'
          >
            {day}
          </span>
        ))}
      </div>
      <div className='bg-foreground/[0.03] grid grid-cols-5 gap-x-1.5 gap-y-2 rounded-lg p-1.5'>
        {TIMELINE_BARS.map((bar) => {
          const barStyle = {
            gridColumn: gridColumnOf(bar),
            '--chip': 'var(--primary)',
          } as React.CSSProperties;

          return (
            <div
              key={bar.title}
              style={barStyle}
              className='chip-3d flex h-8 min-w-0 items-center rounded-md px-2.5 text-xs font-medium'
            >
              <span className='truncate'>{bar.title}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function runsLabelOf(count: number) {
  if (count === 1) {
    return 'Ran once this week';
  }
  return `Ran ${count} times this week`;
}

function AutomationsPreview() {
  return (
    <div className={cn(CARD, 'flex flex-col gap-4 rounded-xl p-4')}>
      <div className='flex items-center justify-between gap-3'>
        <p className='text-sm font-medium'>{RULE.name}</p>
        <Switch defaultChecked aria-label={`Turn ${RULE.name} on or off`} />
      </div>
      <dl className='flex flex-col gap-2.5 text-[13px]'>
        <div className='flex flex-wrap items-center gap-2'>
          <dt className='text-muted-foreground w-12'>When</dt>
          <dd className='flex flex-wrap items-center gap-1.5'>
            <Chip color='var(--muted-foreground)'>{RULE.triggerField}</Chip>
            is
            <Chip color='var(--success)'>{RULE.triggerValue}</Chip>
          </dd>
        </div>
        <div className='flex flex-wrap items-center gap-2'>
          <dt className='text-muted-foreground w-12'>Then</dt>
          <dd className='flex flex-wrap items-center gap-1.5'>
            {RULE.action}
            <Chip color='var(--muted-foreground)'>{RULE.channel}</Chip>
          </dd>
        </div>
      </dl>
      <p className='text-muted-foreground text-xs tabular-nums'>
        {runsLabelOf(RULE.runsThisWeek)}
      </p>
    </div>
  );
}

function plotWidthOf() {
  const horizontalPadding = CHART.left + CHART.right;
  return CHART.width - horizontalPadding;
}

function plotHeightOf() {
  const verticalPadding = CHART.top + CHART.bottom;
  return CHART.height - verticalPadding;
}

function yOf(hours: number) {
  const ratio = hours / CHART.maxHours;
  const remaining = 1 - ratio;
  const plotHeight = plotHeightOf();
  const offset = plotHeight * remaining;
  return CHART.top + offset;
}

function gridHoursOf() {
  const lines: number[] = [];
  for (let hours = 0; hours <= CHART.maxHours; hours += CHART.gridStep) {
    lines.push(hours);
  }
  return lines;
}

function slotWidthOf() {
  return plotWidthOf() / HOURS_BY_DAY.length;
}

function barGeometryOf(entry: DayHours, index: number) {
  const slotWidth = slotWidthOf();
  const width = slotWidth * CHART.barRatio;
  const slotOffset = slotWidth * index;
  const slotStart = CHART.left + slotOffset;
  const freeSpace = slotWidth - width;
  const inset = freeSpace / 2;
  const x = slotStart + inset;
  const y = yOf(entry.hours);
  const baseline = yOf(0);
  const height = baseline - y;
  const halfSlot = slotWidth / 2;
  const center = slotStart + halfSlot;
  return { x, y, width, height, center };
}

function hoursLabelOf(hours: number) {
  const figure = HOURS_FORMAT.format(hours);
  return `${figure} h`;
}

function totalHoursOf(entries: DayHours[]) {
  let total = 0;
  for (const entry of entries) {
    total += entry.hours;
  }
  return total;
}

function ReportsPreview() {
  const gridHours = gridHoursOf();
  const chartRight = CHART.width - CHART.right;
  const labelY = CHART.height - 8;
  const tickX = CHART.left - 6;
  const viewBox = `0 0 ${CHART.width} ${CHART.height}`;
  const totalHours = totalHoursOf(HOURS_BY_DAY);

  return (
    <div className={cn(CARD, 'flex flex-col gap-3 rounded-xl p-4')}>
      <div className='flex items-baseline justify-between gap-3'>
        <div className='flex flex-col'>
          <p className='text-sm font-medium'>Hours this week</p>
          <p className='text-muted-foreground text-xs tabular-nums'>
            {hoursLabelOf(totalHours)} logged
          </p>
        </div>
        <Chip color='var(--muted-foreground)'>Illustrative</Chip>
      </div>
      <svg viewBox={viewBox} aria-hidden='true' className='h-auto w-full'>
        {gridHours.map((hours) => {
          const y = yOf(hours);

          return (
            <g key={hours}>
              <line
                x1={CHART.left}
                x2={chartRight}
                y1={y}
                y2={y}
                className='stroke-border'
                strokeWidth={1}
                vectorEffect='non-scaling-stroke'
              />
              <text
                x={tickX}
                y={y}
                textAnchor='end'
                dominantBaseline='middle'
                className='fill-muted-foreground text-[10px] tabular-nums'
              >
                {hours}h
              </text>
            </g>
          );
        })}
        {HOURS_BY_DAY.map((entry, index) => {
          const bar = barGeometryOf(entry, index);

          return (
            <g key={entry.day}>
              <rect
                x={bar.x}
                y={bar.y}
                width={bar.width}
                height={bar.height}
                rx={5}
                className='fill-primary'
              />
              <text
                x={bar.center}
                y={labelY}
                textAnchor='middle'
                className='fill-muted-foreground text-[10px]'
              >
                {entry.day}
              </text>
            </g>
          );
        })}
      </svg>
      <table className='sr-only'>
        <caption>Hours logged per day this week, illustrative</caption>
        <thead>
          <tr>
            <th scope='col'>Day</th>
            <th scope='col'>Hours</th>
          </tr>
        </thead>
        <tbody>
          {HOURS_BY_DAY.map((entry) => (
            <tr key={entry.day}>
              <th scope='row'>{entry.day}</th>
              <td>{hoursLabelOf(entry.hours)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

const PREVIEW_BY_ID: Record<FeatureId, () => React.ReactNode> = {
  boards: BoardsPreview,
  timeline: TimelinePreview,
  automations: AutomationsPreview,
  reports: ReportsPreview,
};

export function FeaturePreview({ id }: { id: FeatureId }) {
  const Preview = PREVIEW_BY_ID[id];
  return <Preview />;
}

import {
  CalendarIcon,
  ChartLineIcon,
  type Icon,
  LayoutGridIcon,
  ZapIcon,
} from '@/registry/ndeko/lib/icons';

export type FeatureId = 'boards' | 'timeline' | 'automations' | 'reports';

export type Feature = {
  id: FeatureId;
  icon: Icon;
  title: string;
  description: string;
};

export const SECTION = {
  title: 'Board, timeline, rules and report on the same cards',
  description:
    'Every view reads the same cards, so a date moved on the timeline is already moved on the board.',
};

export const FEATURES: Feature[] = [
  {
    id: 'boards',
    icon: LayoutGridIcon,
    title: 'Boards',
    description: 'Lanes for each stage, with owners and labels on every card',
  },
  {
    id: 'timeline',
    icon: CalendarIcon,
    title: 'Timeline',
    description: 'The same cards laid out on the week, so overlaps show early',
  },
  {
    id: 'automations',
    icon: ZapIcon,
    title: 'Automations',
    description: 'Rules that post, assign or move cards when something changes',
  },
  {
    id: 'reports',
    icon: ChartLineIcon,
    title: 'Reports',
    description: 'Where the hours of the week went, day by day',
  },
];

export const DEFAULT_FEATURE_ID: FeatureId = 'boards';

export type MiniCard = {
  title: string;
  label: string;
};

export type MiniLane = {
  title: string;
  cards: MiniCard[];
};

export const MINI_LANES: MiniLane[] = [
  {
    title: 'To do',
    cards: [
      { title: 'Pricing page copy', label: 'Copy' },
      { title: 'Launch photos', label: 'Design' },
    ],
  },
  {
    title: 'In progress',
    cards: [{ title: 'Onboarding checklist', label: 'Product' }],
  },
  {
    title: 'Done',
    cards: [
      { title: 'Beta feedback notes', label: 'Research' },
      { title: 'Press kit', label: 'Design' },
    ],
  },
];

export const WEEK_DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];

export type TimelineBar = {
  title: string;
  startDay: number;
  dayCount: number;
};

export const TIMELINE_BARS: TimelineBar[] = [
  {
    title: 'Pricing page copy',
    startDay: 1,
    dayCount: 2,
  },
  {
    title: 'Onboarding checklist',
    startDay: 2,
    dayCount: 3,
  },
  { title: 'Launch photos', startDay: 3, dayCount: 2 },
  { title: 'Launch email', startDay: 4, dayCount: 2 },
];

export const RULE = {
  name: 'Announce finished work',
  triggerField: 'Status',
  triggerValue: 'Done',
  action: 'Post in',
  channel: '#launch',
  runsThisWeek: 3,
};

export type DayHours = {
  day: string;
  hours: number;
};

export const HOURS_BY_DAY: DayHours[] = [
  { day: 'Mon', hours: 6.5 },
  { day: 'Tue', hours: 7.5 },
  { day: 'Wed', hours: 5 },
  { day: 'Thu', hours: 8 },
  { day: 'Fri', hours: 4.5 },
];
